import 'dart:convert';import 'package:connectivity_plus/connectivity_plus.dart';import 'package:http/http.dart' as http;import 'local_database.dart';
class SyncManager{SyncManager({required this.gateway});final String gateway;Future<int> syncPending()async{final connectivity=await Connectivity().checkConnectivity();if(connectivity.contains(ConnectivityResult.none))return 0;var synced=0;for(final item in await LocalDatabase.instance.pending()){try{final response=await http.post(Uri.parse('$gateway/api/v1/ingestion/cvs'),headers:{'Content-Type':'application/json','Idempotency-Key':item.idempotencyKey},body:jsonEncode({'candidateId':item.id,'vacancyId':item.vacancyId,'channel':'mobile','applicant':{'name':item.name},'resume':{'imagePath':item.imagePath,'localCvScore':item.localCvScore,'interviewScore':item.interviewScore}}));if(response.statusCode>=200&&response.statusCode<300){await LocalDatabase.instance.markSynced(item.id);synced++;}}catch(_){}}return synced;}}
